window.SLIDES=[{"id":"couverture","title":"L'austérité est-elle criminelle ?","part":"Ouverture","html":"\u003cdiv class=\"rev-cover\">\u003cp class=\"rev-cover-kicker\">Macroéconomie L3\u003c/p>\u003ch1>3. L’austérité est-elle criminelle ?\u003c/h1>\u003cp>Arnaud Dyèvre, HEC Paris\u003c/p>\u003cp class=\"rev-cover-term\">Automne 2026\u003c/p>\u003cdiv id=\"pj-cover\" style=\"position:absolute;left:-9999px;width:720px;height:540px\" aria-hidden=\"true\">\u003c/div>\u003c/div>","layout":"cover"},{"id":"vote-debut","title":"En 2010, que fallait-il faire en Grèce&#8239;?","part":"Ouverture","html":"\u003cdiv class=\"p-center\" style=\"gap:26px\">\n      \u003cp class=\"p-sub\">Déficit public de \u003cspan class=\"k-fp\">15,4 %\u003c/span> du PIB en 2009. Taux à dix ans de 5,5 % en décembre 2009, 10,3 % en juillet 2010 : la Grèce ne peut plus emprunter.\u003c/p>\n      \u003cdiv style=\"max-width:1280px\">\u003cdiv>\u003cdiv class=\"ask\">Votre avis · vote à main levée\u003c/div>\u003cdiv class=\"choices \" id=\"pj-vote1\">\u003cbutton class=\"choice\" data-choice=\"A\">\u003cspan class=\"letter\">A\u003c/span>\u003cspan>Réduire le déficit vite, en baissant les dépenses et en relevant les impôts\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"B\">\u003cspan class=\"letter\">B\u003c/span>\u003cspan>Le réduire lentement, sur plusieurs années\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"C\">\u003cspan class=\"letter\">C\u003c/span>\u003cspan>Dépenser davantage pour relancer l'activité\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"D\">\u003cspan class=\"letter\">D\u003c/span>\u003cspan>Cesser de rembourser une partie de la dette\u003c/span>\u003c/button>\u003c/div>\u003c/div>\u003c/div>\n      \n    \u003c/div>","source":"\u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/gov_10dd_edpt1/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, gov_10dd_edpt1 (notification d'avril 2026)\u003c/a> ; \u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/irt_lt_mcby_m/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, irt_lt_mcby_m\u003c/a>, moyennes mensuelles.","prov":"obs"},{"id":"deux-theses","title":"Deux thèses s'opposent depuis la crise grecque","part":"Ouverture","html":"\u003cdiv class=\"p-center\">\u003cdiv class=\"p-grid2\" style=\"gap:40px\">\n      \u003cdiv class=\"pj-card tint-red\">\u003cdiv class=\"h big\">« L'austérité tue »\u003c/div>\u003cp>Couper dans la santé et la protection sociale pendant une récession coûte des vies.\u003c/p>\u003cp class=\"p-sub\" style=\"margin-top:14px\">David Stuckler et Sanjay Basu, \u003ci>The Body Economic\u003c/i> (2013)\u003c/p>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"pj-card tint-blue\">\u003cdiv class=\"h big\">« L'austérité peut relancer l'activité »\u003c/div>\u003cp>Réduire le déficit par des baisses de dépenses plutôt que par des hausses d'impôts évite le plus souvent la récession.\u003c/p>\u003cp class=\"p-sub\" style=\"margin-top:14px\">Alberto Alesina et Silvia Ardagna (2010)\u003c/p>\u003c/div>\u003c/div>\n    \u003c/div>\u003c/div>","source":"\u003ca href=\"https://www.nber.org/papers/w15438\" target=\"_blank\" rel=\"noopener noreferrer\">Alesina et Ardagna (2010), Tax Policy and the Economy\u003c/a>.","prov":null},{"id":"grece-chiffres","title":"Ce qui s'est passé en Grèce","part":"Ouverture","html":"\u003cdiv class=\"p-center\" style=\"gap:22px\">\n      \u003cdiv class=\"p-kpi h\">\u003cdiv class=\"v\">\u003cspan class=\"k-vol\">− 27 %\u003c/span>\u003c/div>\u003cdiv class=\"l\">production (PIB en volume), de 2008 à 2013\u003c/div>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"p-kpi h\">\u003cdiv class=\"v\">\u003cspan class=\"k-cho\">8,0 → 27,8 %\u003c/span>\u003c/div>\u003cdiv class=\"l\">taux de chômage, de 2008 à 2013\u003c/div>\u003c/div>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"2\">\u003cdiv class=\"p-kpi h\">\u003cdiv class=\"v\">\u003cspan class=\"k-fp\">129 → 180 %\u003c/span>\u003c/div>\u003cdiv class=\"l\">dette publique en % du PIB, de 2009 à 2013, malgré l'austérité\u003c/div>\u003c/div>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"3\">\u003cp class=\"p-sub\" style=\"margin-top:10px\">Pour juger : mesurer l'austérité, comprendre avec un modèle pourquoi elle peut réduire la production, chiffrer ce coût, puis relire la crise de la zone euro.\u003c/p>\u003c/div>\n    \u003c/div>","source":"Production et dette : \u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/nama_10_gdp/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, nama_10_gdp (9 octobre 2026)\u003c/a> ; \u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/gov_10dd_edpt1/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, gov_10dd_edpt1 (notification d'avril 2026)\u003c/a>. Chômage : \u003ca href=\"https://economy-finance.ec.europa.eu/economic-research-and-databases/economic-databases/ameco-database_en\" target=\"_blank\" rel=\"noopener noreferrer\">AMECO (printemps 2026)\u003c/a>, définition d'Eurostat.","prov":"obs"},{"id":"france-2027","title":"La France annonce 54 milliards d'euros d'efforts pour 2027","part":"Ouverture","html":"\u003cdiv class=\"p-row\" style=\"gap:46px\">\n      \u003cdiv class=\"p-w55\">\u003cdiv id=\"pj-fr27\" style=\"width:100%;height:600px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow p-col\" style=\"gap:20px\">\n        \u003cdiv class=\"p-kpi md\">\u003cdiv class=\"v\">\u003cspan class=\"k-fp\">5,4 → 5,0 %\u003c/span>\u003c/div>\u003cdiv class=\"l\">déficit public prévu en 2026, puis visé en 2027, en % du PIB\u003c/div>\u003c/div>\n        \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"p-kpi md\">\u003cdiv class=\"v\">\u003cspan class=\"k-fp\">119,3 → 121,7 %\u003c/span>\u003c/div>\u003cdiv class=\"l\">dette publique en % du PIB\u003c/div>\u003c/div>\u003c/div>\n        \u003cdiv class=\"\" data-step=\"2\">\u003cdiv class=\"p-kpi md\">\u003cdiv class=\"v\">\u003cspan class=\"k-vol\">0,5 → 1,0 %\u003c/span>\u003c/div>\u003cdiv class=\"l\">croissance prévue\u003c/div>\u003c/div>\u003c/div>\n      \u003c/div>\u003c/div>","source":"1995-2025 : \u003ca href=\"https://www.insee.fr/fr/statistiques/8997691\" target=\"_blank\" rel=\"noopener noreferrer\">Insee Première n° 2106 (mai 2026), compte des administrations publiques en 2025\u003c/a>. 2026 et 2027 : \u003ca href=\"https://www.assemblee-nationale.fr/dyn/17/textes/l17b3210_projet-loi.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Projet de loi de finances pour 2027, n° 3210 (1er octobre 2026)\u003c/a>, article liminaire et exposé des motifs.","prov":"obs"},{"id":"question-2027","title":"Une question pour la fin du cours","part":"Ouverture","html":"\u003cdiv class=\"p-center\" style=\"gap:36px\">\n      \u003cp class=\"p-stmt\">Combien coûteront ces 54 milliards d'efforts en croissance ?\u003c/p>\n      \u003cp class=\"p-sub\">Réponse en partie 4, avec le modèle de la partie 2.\u003c/p>\n    \u003c/div>","prov":null},{"id":"plan","title":"Les cinq parties du chapitre","part":"Ouverture","html":"\u003cdiv class=\"p-center\" style=\"gap:22px\">\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">1\u003c/span>\u003cspan class=\"q\">Qu’est-ce que l’austérité ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">2\u003c/span>\u003cspan class=\"q\">Dépenser moins, produire moins ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">3\u003c/span>\u003cspan class=\"q\">L’austérité en récession\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">4\u003c/span>\u003cspan class=\"q\">Combien coûte l’austérité ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">5\u003c/span>\u003cspan class=\"q\">La crise de la zone euro\u003c/span>\u003c/div>\u003c/div>","prov":null},{"id":"p1","title":"Qu’est-ce que l’austérité&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center rev-section-overview\" style=\"gap:22px\">\u003cdiv class=\"pj-plan-row is-current\">\u003cspan class=\"n\">1\u003c/span>\u003cspan class=\"q\">Qu’est-ce que l’austérité ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">2\u003c/span>\u003cspan class=\"q\">Dépenser moins, produire moins ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">3\u003c/span>\u003cspan class=\"q\">L’austérité en récession\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">4\u003c/span>\u003cspan class=\"q\">Combien coûte l’austérité ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">5\u003c/span>\u003cspan class=\"q\">La crise de la zone euro\u003c/span>\u003c/div>\u003c/div>","layout":"section"},{"id":"budget","title":"Le déficit est l'écart entre dépenses et recettes","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-row\" style=\"gap:50px\">\n      \u003cdiv class=\"p-w55\">\u003cdiv id=\"pj-apu\" style=\"width:100%;height:600px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow\">\u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"def compact\" data-term=\"Solde public\">\u003cdiv class=\"def-label\">Définition\u003c/div>\u003cdiv class=\"def-term\">Solde public\u003c/div>\u003cp class=\"def-text\">Recettes moins dépenses des administrations publiques (État, collectivités locales, sécurité sociale) au cours d'une année. Négatif, c'est un \u003cb>déficit\u003c/b>.\u003c/p>\u003c/div>\u003c/div>\u003c/div>\n    \u003c/div>","source":"\u003ca href=\"https://www.insee.fr/fr/statistiques/8997691\" target=\"_blank\" rel=\"noopener noreferrer\">Insee Première n° 2106 (mai 2026), compte des administrations publiques en 2025\u003c/a> : figures 1 et 2. Dépenses y compris crédits d'impôt.","prov":"obs"},{"id":"interets","title":"Combien l'État a-t-il emprunté en 2025&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\" style=\"gap:30px\">\n      \u003cdiv class=\"p-kpi h\">\u003cdiv class=\"v\">\u003cspan class=\"k-fp\">152,5 Md€\u003c/span>\u003c/div>\u003cdiv class=\"l\">de déficit public, soit 5,1 % du PIB\u003c/div>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"p-kpi h\">\u003cdiv class=\"v\">\u003cspan class=\"k-moins\">64,7 Md€\u003c/span>\u003c/div>\u003cdiv class=\"l\">d'intérêts versés sur la dette, soit 2,2 % du PIB, en hausse de 11 % en un an\u003c/div>\u003c/div>\u003c/div>\n    \u003c/div>","source":"\u003ca href=\"https://www.insee.fr/fr/statistiques/8997691\" target=\"_blank\" rel=\"noopener noreferrer\">Insee Première n° 2106 (mai 2026), compte des administrations publiques en 2025\u003c/a> : figures 2 et 4. Intérêts hors correction des services d'intermédiation financière (Sifim).","prov":"obs"},{"id":"solde-primaire","title":"L'État emprunterait-il sans la charge de la dette&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\">\u003cdiv style=\"max-width:1240px;margin:0 auto;width:100%\">\u003cdiv class=\"fiche \">\u003cdiv class=\"fiche-head\">\u003cspan class=\"fiche-lbl\">À savoir utiliser\u003c/span>\u003cspan class=\"fiche-name\">Solde primaire\u003c/span>\u003c/div>\u003cdiv class=\"fiche-f\">\u003cspan class=\"k-fp\">solde primaire\u003c/span> = \u003cspan class=\"k-fp\">solde public\u003c/span> + \u003cspan class=\"k-moins\">intérêts versés\u003c/span>\u003c/div>\u003cdiv class=\"fiche-ex\" data-step=\"1\">\u003cspan class=\"lbl\">Exemple\u003c/span>France, 2025 : \u003cspan class=\"k-fp\">− 5,1\u003c/span> + \u003cspan class=\"k-moins\">2,2\u003c/span> = \u003cspan class=\"k-res\">− 2,9 %\u003c/span> du PIB. Même sans intérêts à payer, l'État emprunterait encore.\u003c/div>\u003cdiv class=\"fiche-trap\" data-step=\"2\">\u003cspan class=\"lbl\">Piège\u003c/span>retrancher les intérêts au lieu de les ajouter.\u003c/div>\u003c/div>\u003c/div>\u003c/div>","source":"\u003ca href=\"https://www.insee.fr/fr/statistiques/8997691\" target=\"_blank\" rel=\"noopener noreferrer\">Insee Première n° 2106 (mai 2026), compte des administrations publiques en 2025\u003c/a>, 2025.","prov":"obs"},{"id":"dette","title":"Le déficit est un flux, la dette un stock","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-row\" style=\"gap:50px\">\n      \u003cdiv class=\"p-w55\">\u003cdiv id=\"pj-dette\" style=\"width:100%;height:600px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow\">\u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"def compact\" data-term=\"Dette publique\">\u003cdiv class=\"def-label\">Définition\u003c/div>\u003cdiv class=\"def-term\">Dette publique\u003c/div>\u003cp class=\"def-text\">Ce que doivent les administrations publiques à une date donnée. Le déficit de l'année s'y ajoute, à peu de chose près.\u003c/p>\u003c/div>\u003c/div>\u003c/div>\n    \u003c/div>","source":"Dette au sens de Maastricht : \u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/gov_10dd_edpt1/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, gov_10dd_edpt1 (notification d'avril 2026)\u003c/a>, rapportée au PIB des comptes nationaux de l'Insee. Fin juin 2026 : \u003ca href=\"https://www.insee.fr/fr/statistiques/9053525\" target=\"_blank\" rel=\"noopener noreferrer\">Insee, Informations rapides n° 239 (29 septembre 2026)\u003c/a>.","prov":"obs"},{"id":"ratio","title":"Pourquoi rapporter la dette au PIB&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\">\u003cdiv style=\"max-width:1240px;margin:0 auto;width:100%\">\u003cdiv class=\"fiche \">\u003cdiv class=\"fiche-head\">\u003cspan class=\"fiche-lbl\">À savoir utiliser\u003c/span>\u003cspan class=\"fiche-name\">Ratio de dette\u003c/span>\u003c/div>\u003cdiv class=\"fiche-f\">\u003cspan class=\"k-fp\">ratio de dette\u003c/span> = \u003cspan class=\"k-fp\">dette\u003c/span> / \u003cspan class=\"k-nom\">PIB nominal\u003c/span>\u003c/div>\u003cdiv class=\"fiche-ex\" data-step=\"1\">\u003cspan class=\"lbl\">Exemple\u003c/span>fin 2025 : \u003cspan class=\"k-fp\">3 460,5 Md€\u003c/span> / \u003cspan class=\"k-nom\">2 991,1 Md€\u003c/span> = \u003cspan class=\"k-res\">115,7 %\u003c/span>.\u003c/div>\u003cdiv class=\"fiche-trap\" data-step=\"2\">\u003cspan class=\"lbl\">Piège\u003c/span>comparer des dettes en euros entre pays ou entre périodes : on les rapporte au PIB, l'assiette de l'impôt.\u003c/div>\u003c/div>\u003c/div>\u003c/div>","source":"\u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/gov_10dd_edpt1/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, gov_10dd_edpt1 (notification d'avril 2026)\u003c/a> ; \u003ca href=\"https://www.insee.fr/fr/statistiques/8997691\" target=\"_blank\" rel=\"noopener noreferrer\">Insee Première n° 2106 (mai 2026), compte des administrations publiques en 2025\u003c/a>.","prov":"obs"},{"id":"dette-verif","title":"Le ratio de dette peut-il baisser sans remboursement&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\" style=\"gap:36px\">\n      \u003cp class=\"p-txt\">\u003cspan class=\"pj-tag\">Vérifiez · 1 minute\u003c/span> La dette reste à \u003cspan class=\"k-fp\">3 460,5 Md€\u003c/span> et le PIB nominal augmente de 3 %. Que devient le ratio ?\u003c/p>\n      \u003c/div>","source":"Calcul sur les chiffres de 2025 : \u003ca href=\"https://www.insee.fr/fr/statistiques/8997691\" target=\"_blank\" rel=\"noopener noreferrer\">Insee Première n° 2106 (mai 2026), compte des administrations publiques en 2025\u003c/a>.","prov":"mixte"},{"id":"effort","title":"54 milliards d'efforts, et des dépenses qui augmentent&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\">\u003cdiv class=\"p-grid3\" style=\"gap:26px\">\n      \u003cdiv>\u003cdiv class=\"pj-measure\">\u003cdiv class=\"t\">1. Les dépenses\u003c/div>\u003cdiv class=\"nb\">\u003cspan class=\"k-dep\">+ 40 Md€\u003c/span>\u003c/div>\u003cp>de 1 742 Md€ en 2026 à 1 782 Md€ en 2027\u003c/p>\u003c/div>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"pj-measure\">\u003cdiv class=\"t\">2. Les « efforts »\u003c/div>\u003cdiv class=\"nb\">\u003cspan class=\"k-res\">54 Md€\u003c/span>\u003c/div>\u003cp>par rapport à l'évolution sans mesures nouvelles, où le déficit atteindrait 6,4 %\u003c/p>\u003c/div>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"2\">\u003cdiv class=\"pj-measure\">\u003cdiv class=\"t\">3. Le solde structurel\u003c/div>\u003cdiv class=\"nb\">\u003cspan class=\"k-fp\">+ 0,5 point\u003c/span>\u003c/div>\u003cp>de −5,1 % à −4,6 % du PIB potentiel, environ 16 Md€\u003c/p>\u003c/div>\u003c/div>\n    \u003c/div>\u003c/div>","source":"\u003ca href=\"https://www.assemblee-nationale.fr/dyn/17/textes/l17b3210_projet-loi.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Projet de loi de finances pour 2027, n° 3210 (1er octobre 2026)\u003c/a> : article liminaire, exposé général des motifs (p. 12). Montant en euros : calcul du cours avec le PIB implicite du PLF (3 132 Md€).","prov":"obs"},{"id":"consolidation","title":"Ce que les économistes appellent austérité","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\" style=\"gap:30px\">\n      \u003cdiv class=\"def \" data-term=\"Consolidation budgétaire (austérité)\">\u003cdiv class=\"def-label\">Définition\u003c/div>\u003cdiv class=\"def-term\">Consolidation budgétaire\u003c/div>\u003cp class=\"def-text\">Politique qui améliore délibérément le solde public, en freinant les dépenses ou en augmentant les impôts par rapport à leur évolution sans mesures nouvelles. Le mot \u003cb>austérité\u003c/b> désigne la même politique, souvent pour la critiquer.\u003c/p>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"warn\">\u003cspan class=\"lbl\">À ne pas confondre\u003c/span>Un « effort » se mesure par rapport à une trajectoire qui n'a pas eu lieu. Les dépenses et le solde, eux, s'observent.\u003c/div>\u003c/div>\n    \u003c/div>","prov":null},{"id":"pourquoi","title":"Pourquoi un État réduit-il son déficit&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\">\u003cdiv class=\"p-grid2\" style=\"gap:26px 34px\">\u003cdiv>\u003cdiv class=\"pj-card\" style=\"height:100%\">\u003cdiv class=\"h big\">Stabiliser la dette\u003c/div>\u003cp>Tant que le déficit reste élevé, le ratio de dette augmente (chapitre 6).\u003c/p>\u003c/div>\u003c/div>\u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"pj-card\" style=\"height:100%\">\u003cdiv class=\"h big\">Garder la confiance des prêteurs\u003c/div>\u003cp>Quand ils doutent, ils exigent un taux d'intérêt plus élevé.\u003c/p>\u003c/div>\u003c/div>\u003cdiv class=\"\" data-step=\"2\">\u003cdiv class=\"pj-card\" style=\"height:100%\">\u003cdiv class=\"h big\">Respecter les règles européennes\u003c/div>\u003cp>Un déficit sous 3 % du PIB ; la France est en procédure pour déficit excessif depuis juillet 2024.\u003c/p>\u003c/div>\u003c/div>\u003cdiv class=\"\" data-step=\"3\">\u003cdiv class=\"pj-card\" style=\"height:100%\">\u003cdiv class=\"h big\">Freiner une économie en surchauffe\u003c/div>\u003cp>Quand la production dépasse son potentiel, moins de demande publique limite l'inflation.\u003c/p>\u003c/div>\u003c/div>\u003c/div>\u003c/div>","source":"\u003ca href=\"https://eur-lex.europa.eu/eli/dec/2024/2122/oj\" target=\"_blank\" rel=\"noopener noreferrer\">décision (UE) 2024/2122 du Conseil (26 juillet 2024)\u003c/a>.","prov":null},{"id":"taux","title":"Quand les prêteurs doutent, le taux d'intérêt monte","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-row\" style=\"gap:46px\">\n      \u003cdiv class=\"p-w60\">\u003cdiv id=\"pj-taux\" style=\"width:100%;height:600px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow p-col\" style=\"gap:28px\">\n        \u003cp class=\"p-txt\">Grèce : \u003cspan class=\"k-moins\">29,2 %\u003c/span> en février 2012.\u003c/p>\n        \u003cdiv class=\"\" data-step=\"1\">\u003cp class=\"p-txt\">En septembre 2026, la France emprunte à \u003cspan class=\"k-moins\">4,44 %\u003c/span>, plus cher que la Grèce (4,22 %) et l'Italie (4,36 %).\u003c/p>\u003c/div>\n      \u003c/div>\u003c/div>","source":"\u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/irt_lt_mcby_m/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, irt_lt_mcby_m (taux à long terme du critère de convergence, moyennes mensuelles)\u003c/a>, moyennes mensuelles.","prov":"obs"},{"id":"preteurs-q","title":"Qui prête à l'État français&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\" style=\"gap:24px\">\u003cdiv style=\"max-width:1200px\">\n      \u003cdiv>\u003cdiv class=\"ask\">Quelle part des titres de la dette de l'État est détenue par des non-résidents ?\u003c/div>\u003cdiv class=\"choices inline\" id=\"pj-pret\">\u003cbutton class=\"choice\" data-choice=\"A\">\u003cspan class=\"letter\">A\u003c/span>\u003cspan>moins d'un quart\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"B\">\u003cspan class=\"letter\">B\u003c/span>\u003cspan>environ un tiers\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"C\">\u003cspan class=\"letter\">C\u003c/span>\u003cspan>plus de la moitié\u003c/span>\u003c/button>\u003c/div>\u003c/div>\n      \u003c/div>\n    \u003c/div>","source":"\u003ca href=\"https://www.aft.gouv.fr/fr/publications/bulletins-mensuels\" target=\"_blank\" rel=\"noopener noreferrer\">Agence France Trésor, Bulletin mensuel n° 436 (septembre 2026)\u003c/a>, d'après la Banque de France.","prov":"obs"},{"id":"preteurs","title":"Plus de la moitié de la dette de l'État est détenue hors de France","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-row\" style=\"gap:44px\">\n      \u003cdiv class=\"p-w55\">\u003cp class=\"p-lbl\">Détenteurs de la dette négociable de l'État, fin mars 2026, en %\u003c/p>\u003cdiv id=\"pj-pret-chart\" style=\"width:100%;height:560px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow p-swap\">\n        \u003cdiv data-until=\"0\">\u003cdiv class=\"def compact\" data-term=\"Dette négociable\">\u003cdiv class=\"def-label\">Définition\u003c/div>\u003cdiv class=\"def-term\">Dette négociable\u003c/div>\u003cp class=\"def-text\">Titres que l'État vend pour emprunter : obligations (OAT) et bons du Trésor. Ceux qui les achètent peuvent les revendre à tout moment.\u003c/p>\u003c/div>\u003c/div>\n        \u003cdiv data-step=\"1\" data-until=\"1\">\u003cdiv class=\"p-col\" style=\"gap:18px\">\u003cp class=\"p-lbl\">L'Eurosystème se retire\u003c/p>\u003cp class=\"p-txt\">Titres publics français détenus par la Banque de France et la BCE : \u003cspan class=\"k-fp\">839 Md€\u003c/span> en janvier 2023, \u003cspan class=\"k-fp\">597 Md€\u003c/span> en septembre 2026.\u003c/p>\u003cp class=\"p-sub\">Elles ne remplacent plus les titres qui arrivent à échéance.\u003c/p>\u003c/div>\u003c/div>\n        \u003cdiv data-step=\"2\">\u003cdiv class=\"callout\">En 2027, l'État doit emprunter \u003cspan class=\"k-fp\">340 Md€\u003c/span>, dont 189 pour rembourser des titres arrivés à échéance : il doit trouver des acheteurs.\u003c/div>\u003c/div>\n      \u003c/div>\u003c/div>","source":"\u003ca href=\"https://www.aft.gouv.fr/fr/publications/bulletins-mensuels\" target=\"_blank\" rel=\"noopener noreferrer\">AFT, Bulletin mensuel n° 436\u003c/a>, d'après la Banque de France ; \u003ca href=\"https://www.ecb.europa.eu/mopo/implement/app/html/index.en.html\" target=\"_blank\" rel=\"noopener noreferrer\">BCE, programmes PSPP et PEPP\u003c/a>, cumul des achats nets ; \u003ca href=\"https://www.assemblee-nationale.fr/dyn/17/textes/l17b3210_projet-loi.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">PLF 2027\u003c/a>, tableau de financement.","prov":"obs"},{"id":"spread","title":"Combien la France paie-t-elle de plus que l'Allemagne&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\" style=\"gap:30px\">\n      \u003cdiv class=\"def \" data-term=\"Spread (écart de taux)\">\u003cdiv class=\"def-label\">Définition\u003c/div>\u003cdiv class=\"def-term\">Spread (écart de taux)\u003c/div>\u003cp class=\"def-text\">Différence entre le taux auquel un État emprunte et celui de l'Allemagne, pour la même durée : la prime que les prêteurs exigent pour lui prêter plutôt qu'à l'État jugé le plus sûr.\u003c/p>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cp class=\"p-stmt\">Septembre 2026 : \u003cspan class=\"k-moins\">4,44 %\u003c/span> − 3,47 % = \u003cspan class=\"k-res\">0,97 point\u003c/span> = \u003cspan class=\"k-res\">97 points de base\u003c/span>\u003c/p>\n        \u003cp class=\"p-sub\">1 point de base = 0,01 point de pourcentage.\u003c/p>\u003c/div>\n    \u003c/div>","source":"\u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/irt_lt_mcby_m/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, irt_lt_mcby_m (taux à long terme du critère de convergence, moyennes mensuelles)\u003c/a> ; écart : calcul du cours.","prov":"obs"},{"id":"spread-zoom","title":"Depuis 2024, la France paie de plus en plus cher","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-row\" style=\"gap:40px\">\n      \u003cdiv class=\"p-w60\">\u003cp class=\"p-lbl\">Écart de taux à dix ans avec l'Allemagne, points de base, moyennes mensuelles\u003c/p>\u003cdiv id=\"pj-spread-chart\" style=\"width:100%;height:580px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow p-swap\">\n        \u003cdiv data-until=\"0\">\u003cdiv class=\"p-col\" style=\"gap:16px\">\u003cp class=\"p-lbl\">Septembre 2026, moyenne du mois\u003c/p>\u003cp class=\"p-txt\" style=\"margin:0\">France \u003cspan class=\"k-fp\">97\u003c/span>, Italie 89, Espagne 45\u003c/p>\u003cp class=\"p-sub\">Mai 2024 : France 51, Italie 132.\u003c/p>\u003c/div>\u003c/div>\n        \u003cdiv data-step=\"1\" data-until=\"1\">\u003cdiv class=\"p-col\" style=\"gap:16px\">\u003cp class=\"p-lbl\">Début octobre 2026\u003c/p>\u003cp class=\"p-txt\" style=\"margin:0\">De \u003cspan class=\"k-fp\">131\u003c/span> à \u003cspan class=\"k-fp\">158\u003c/span> points de base selon les jours.\u003c/p>\u003cp class=\"p-sub\">Cotations citées par la presse. En moyenne mensuelle, l'écart n'avait dépassé 100 qu'entre novembre 2011 et juillet 2012.\u003c/p>\u003c/div>\u003c/div>\n        \u003cdiv data-step=\"2\">\u003cdiv class=\"callout\">Un point de plus sur les 340 Md€ empruntés en 2027 : \u003cspan class=\"k-moins\">3,4 Md€\u003c/span> d'intérêts en plus chaque année, pendant toute la durée des titres.\u003c/div>\u003c/div>\n      \u003c/div>\u003c/div>","source":"\u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/irt_lt_mcby_m/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, irt_lt_mcby_m\u003c/a>, moyennes mensuelles ; octobre : cotations de marché citées par Boursier.com (2 octobre 2026), QuiFinanza et Teleborsa (6 octobre 2026), détail dans data/raw/faits_verifies/ ; \u003ca href=\"https://www.assemblee-nationale.fr/dyn/17/textes/l17b3210_projet-loi.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">PLF 2027\u003c/a>.","prov":"obs"},{"id":"p1-verif1","title":"Le déficit grec de 2009 venait-il des intérêts&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\" style=\"gap:36px\">\n      \u003cp class=\"p-txt\">\u003cspan class=\"pj-tag\">Vérifiez · 1 minute\u003c/span> En 2009, la Grèce a un solde public de \u003cspan class=\"k-fp\">−15,4 %\u003c/span> du PIB et verse des intérêts égaux à \u003cspan class=\"k-moins\">5,1 %\u003c/span> du PIB. Quel est son solde primaire ?\u003c/p>\n      \u003c/div>","source":"\u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/gov_10dd_edpt1/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, gov_10dd_edpt1 (notification d'avril 2026)\u003c/a>.","prov":"obs"},{"id":"p1-verif2","title":"D'où vient la hausse du taux français&#8239;?","part":"Partie 1 · Qu’est-ce que l’austérité ?","html":"\u003cdiv class=\"p-center\" style=\"gap:36px\">\n      \u003cp class=\"p-txt\">\u003cspan class=\"pj-tag\">Vérifiez · 1 minute\u003c/span> De mai 2024 à septembre 2026, la France passe de 3,03 % à 4,44 %, l'Allemagne de 2,52 % à 3,47 %. Quelle part de la hausse vient de la France elle-même ?\u003c/p>\n      \u003c/div>","source":"\u003ca href=\"https://ec.europa.eu/eurostat/databrowser/view/irt_lt_mcby_m/default/table\" target=\"_blank\" rel=\"noopener noreferrer\">Eurostat, irt_lt_mcby_m (taux à long terme du critère de convergence, moyennes mensuelles)\u003c/a>.","prov":"obs"},{"id":"p2","title":"Dépenser moins, produire moins&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center rev-section-overview\" style=\"gap:22px\">\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">1\u003c/span>\u003cspan class=\"q\">Qu’est-ce que l’austérité ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row is-current\">\u003cspan class=\"n\">2\u003c/span>\u003cspan class=\"q\">Dépenser moins, produire moins ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">3\u003c/span>\u003cspan class=\"q\">L’austérité en récession\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">4\u003c/span>\u003cspan class=\"q\">Combien coûte l’austérité ?\u003c/span>\u003c/div>\u003cdiv class=\"pj-plan-row\">\u003cspan class=\"n\">5\u003c/span>\u003cspan class=\"q\">La crise de la zone euro\u003c/span>\u003c/div>\u003c/div>","layout":"section"},{"id":"demande","title":"À court terme, la production suit la demande","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:40px\">\n      \u003cdiv class=\"ident wide\">\n        \u003cdiv class=\"term t-vol\">\u003cdiv class=\"f\">\u003cvar>Y\u003c/var>\u003c/div>\u003cdiv class=\"lbl\">PIB\u003c/div>\u003cdiv class=\"u\">2 991 Md€\u003cbr>\u003cspan class=\"pt\">100 %\u003c/span>\u003c/div>\u003c/div>\u003cdiv class=\"op\">=\u003c/div>\n        \u003cdiv class=\"term t-conso\">\u003cdiv class=\"f\">\u003cvar>C\u003c/var>\u003c/div>\u003cdiv class=\"lbl\">consommation privée\u003c/div>\u003cdiv class=\"u\">1 615 Md€\u003cbr>\u003cspan class=\"pt\">54 %\u003c/span>\u003c/div>\u003c/div>\u003cdiv class=\"op\">+\u003c/div>\n        \u003cdiv class=\"term t-dep\">\u003cdiv class=\"f\">\u003cvar>I\u003c/var>\u003c/div>\u003cdiv class=\"lbl\">investissement\u003c/div>\u003cdiv class=\"u\">670 Md€\u003cbr>\u003cspan class=\"pt\">22 %\u003c/span>\u003c/div>\u003c/div>\u003cdiv class=\"op\">+\u003c/div>\n        \u003cdiv class=\"term t-dep\">\u003cdiv class=\"f\">\u003cvar>G\u003c/var>\u003c/div>\u003cdiv class=\"lbl\">consommation publique\u003c/div>\u003cdiv class=\"u\">720 Md€\u003cbr>\u003cspan class=\"pt\">24 %\u003c/span>\u003c/div>\u003c/div>\u003cdiv class=\"op\">+\u003c/div>\n        \u003cdiv class=\"term t-dep\">\u003cdiv class=\"f\">\u003cvar>X\u003c/var>\u003c/div>\u003cdiv class=\"lbl\">exportations\u003c/div>\u003cdiv class=\"u\">1 009 Md€\u003cbr>\u003cspan class=\"pt\">34 %\u003c/span>\u003c/div>\u003c/div>\u003cdiv class=\"op\">−\u003c/div>\n        \u003cdiv class=\"term t-moins\">\u003cdiv class=\"f\">\u003cvar>M\u003c/var>\u003c/div>\u003cdiv class=\"lbl\">importations\u003c/div>\u003cdiv class=\"u\">1 024 Md€\u003cbr>\u003cspan class=\"pt\">34 %\u003c/span>\u003c/div>\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cp class=\"p-stmt sm\" style=\"text-align:center\">Au chapitre 1, une comptabilité. À court terme, un comportement : les entreprises produisent ce qu'on leur achète.\u003c/p>\u003c/div>\n    \u003c/div>","source":"\u003ca href=\"https://www.insee.fr/fr/statistiques/8988823?sommaire=8988934\" target=\"_blank\" rel=\"noopener noreferrer\">Insee, comptes nationaux annuels base 2020 (tableaux 1.101 et 1.102, mai 2026)\u003c/a> : France, 2025, milliards d'euros et part du PIB. \u003cvar>C\u003c/var> : ménages et institutions sans but lucratif ; \u003cvar>G\u003c/var> : consommation des administrations publiques.","prov":"obs"},{"id":"demande-def","title":"Moins de dépenses publiques, moins de production","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:30px\">\n      \u003cdiv class=\"def \" data-term=\"Demande globale\">\u003cdiv class=\"def-label\">Définition\u003c/div>\u003cdiv class=\"def-term\">Demande globale\u003c/div>\u003cp class=\"def-text\">Dépense totale en biens et services produits dans le pays : consommation, investissement, dépenses publiques et exportations, moins les importations.\u003c/p>\u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"callout\">\u003cspan class=\"lbl\">À retenir\u003c/span>Si l'État dépense 10 milliards de moins, la production baisse d'abord de 10 milliards. Puis ceux dont le revenu a baissé dépensent moins à leur tour : la croix keynésienne dit où cette chaîne s'arrête.\u003c/div>\u003c/div>\n    \u003c/div>","prov":null},{"id":"prix-q","title":"Les prix s'ajustent-ils vite&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:24px\">\u003cdiv style=\"max-width:1200px\">\n      \u003cdiv>\u003cdiv class=\"ask\">Dans la zone euro, quelle part des prix à la consommation change en un mois ?\u003c/div>\u003cdiv class=\"choices inline\" id=\"pj-prix\">\u003cbutton class=\"choice\" data-choice=\"A\">\u003cspan class=\"letter\">A\u003c/span>\u003cspan>environ 5 %\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"B\">\u003cspan class=\"letter\">B\u003c/span>\u003cspan>environ 15 %\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"C\">\u003cspan class=\"letter\">C\u003c/span>\u003cspan>environ 50 %\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"D\">\u003cspan class=\"letter\">D\u003c/span>\u003cspan>presque tous\u003c/span>\u003c/button>\u003c/div>\u003c/div>\n      \u003c/div>\n    \u003c/div>","source":"\u003ca href=\"https://www.ecb.europa.eu/pub/pdf/scpwps/ecbwp524.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Dhyne et al. (2005), « Price setting in the euro area », BCE, document de travail n° 524\u003c/a>.","prov":"obs"},{"id":"prix","title":"Les services changent rarement de prix","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-row\" style=\"gap:50px\">\n      \u003cdiv class=\"p-w60\">\u003cdiv id=\"pj-prix-chart\" style=\"width:100%;height:560px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow p-col\" style=\"gap:26px\">\u003cp class=\"p-txt\">Chaque mois, \u003cspan class=\"k-vol\">78 %\u003c/span> des prix de l'énergie changent, contre \u003cspan class=\"k-vol\">5,6 %\u003c/span> des prix des services.\u003c/p>\n        \u003cp class=\"p-sub\">Ensemble des prix : 15,1 % par mois dans la zone euro, 24,8 % aux États-Unis.\u003c/p>\u003c/div>\n    \u003c/div>","source":"\u003ca href=\"https://www.ecb.europa.eu/pub/pdf/scpwps/ecbwp524.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Dhyne et al. (2005), « Price setting in the euro area », BCE, document de travail n° 524\u003c/a>, p. 6, 13 et 18 : fréquence mensuelle moyenne des changements de prix, zone euro, échantillon commun de 50 produits, 1996-2001.","prov":"obs"},{"id":"prix-hyp","title":"Pourquoi les prix n'apparaissent-ils pas&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:30px\">\n      \u003cdiv class=\"p-grid2\" style=\"gap:34px\">\n        \u003cdiv class=\"pj-card\">\u003cdiv class=\"h\">En microéconomie\u003c/div>\u003cp>Sur un marché concurrentiel, le prix s'ajuste jusqu'à égaliser l'offre et la demande.\u003c/p>\u003c/div>\n        \u003cdiv class=\"pj-card\">\u003cdiv class=\"h\">À court terme, en macroéconomie\u003c/div>\u003cp>La plupart des prix bougent peu. Quand la demande baisse, les entreprises vendent moins au même prix et produisent moins.\u003c/p>\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"callout\">\u003cspan class=\"lbl\">Hypothèse du modèle\u003c/span>Dans la croix keynésienne, les prix sont fixes : ce sont les quantités produites qui s'ajustent à la demande. Les prix reviennent au chapitre 5.\u003c/div>\u003c/div>\n    \u003c/div>","prov":null},{"id":"pmc-q","title":"Un euro de revenu en plus, combien de consommation en plus&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:24px\">\u003cdiv style=\"max-width:1200px\">\n      \u003cdiv>\u003cdiv class=\"ask\">Des ménages italiens imaginent recevoir par surprise un mois de revenu. Quelle part disent-ils dépenser ?\u003c/div>\u003cdiv class=\"choices inline\" id=\"pj-pmc\">\u003cbutton class=\"choice\" data-choice=\"A\">\u003cspan class=\"letter\">A\u003c/span>\u003cspan>moins de 25 %\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"B\">\u003cspan class=\"letter\">B\u003c/span>\u003cspan>entre 25 et 50 %\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"C\">\u003cspan class=\"letter\">C\u003c/span>\u003cspan>entre 50 et 75 %\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"D\">\u003cspan class=\"letter\">D\u003c/span>\u003cspan>plus de 75 %\u003c/span>\u003c/button>\u003c/div>\u003c/div>\n      \u003c/div>\n    \u003c/div>","source":"\u003ca href=\"https://doi.org/10.1257/mac.6.4.107\" target=\"_blank\" rel=\"noopener noreferrer\">Jappelli et Pistaferri (2014), AEJ: Macroeconomics\u003c/a>, enquête de la Banque d'Italie (2010).","prov":"obs"},{"id":"pmc","title":"La consommation dépend du revenu disponible","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\">\u003cdiv style=\"max-width:1280px;margin:0 auto;width:100%\">\u003cdiv class=\"fiche \">\u003cdiv class=\"fiche-head\">\u003cspan class=\"fiche-lbl\">À savoir utiliser\u003c/span>\u003cspan class=\"fiche-name\">Fonction de consommation\u003c/span>\u003c/div>\u003cdiv class=\"fiche-f\">\u003cspan class=\"k-conso\">\u003cvar>C\u003c/var>\u003c/span> = \u003cspan class=\"k-conso\">\u003cvar>C\u003c/var>\u003csub>0\u003c/sub>\u003c/span> + \u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span> (\u003cspan class=\"k-vol\">\u003cvar>Y\u003c/var>\u003c/span> − \u003cspan class=\"k-moins\">\u003cvar>T\u003c/var>\u003c/span>)\u003c/div>\u003cdiv class=\"fiche-vars inline\">\u003cspan class=\"vp\">\u003cspan class=\"sym\">\u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span>\u003c/span>\u003cspan class=\"mean\">propension marginale à consommer\u003c/span>\u003c/span>\u003cspan class=\"vp\">\u003cspan class=\"sym\">\u003cvar>Y\u003c/var> − \u003cvar>T\u003c/var>\u003c/span>\u003cspan class=\"mean\">revenu disponible\u003c/span>\u003c/span>\u003c/div>\u003cdiv class=\"fiche-ex\" data-step=\"1\">\u003cspan class=\"lbl\">Exemple\u003c/span>\u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span> = 0,5 : 100 € de revenu disponible en plus donnent \u003cspan class=\"k-conso\">50 €\u003c/span> de consommation en plus, et 50 € d'épargne.\u003c/div>\u003cdiv class=\"fiche-trap\" data-step=\"2\">\u003cspan class=\"lbl\">Piège\u003c/span>\u003cvar>c\u003c/var> est la part dépensée d'un euro \u003cb>supplémentaire\u003c/b>, pas la part du revenu consommée en moyenne.\u003c/div>\u003c/div>\u003c/div>\u003c/div>","prov":"fictif"},{"id":"droite-dg","title":"Comment trace-t-on la droite de demande globale&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-row\" style=\"gap:40px\">\n      \u003cdiv style=\"flex:0 0 720px\">\u003cdiv id=\"pj-dg-chart\" style=\"width:720px;height:620px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow\">\u003cdiv class=\"pj-steps\">\n        \u003cdiv>\u003cdiv class=\"pj-st\">\u003cdiv class=\"l\">Ce qui ne dépend pas de la production\u003c/div>\u003cdiv class=\"v\">\u003cspan class=\"k-conso\">\u003cvar>C\u003c/var>\u003csub>0\u003c/sub>\u003c/span> + \u003cspan class=\"k-dep\">\u003cvar>I\u003c/var>\u003c/span> + \u003cspan class=\"k-dep\">\u003cvar>G\u003c/var>\u003c/span> = 100 + 150 + 150 = \u003cspan class=\"k-dep\">400\u003c/span>\u003c/div>\u003c/div>\u003c/div>\n        \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"pj-st\">\u003cdiv class=\"l\">Chaque euro produit est un euro de revenu, dont les ménages dépensent\u003c/div>\u003cdiv class=\"v\">\u003cspan class=\"k-conso\">\u003cvar>c\u003c/var> = 0,6\u003c/span>\u003c/div>\u003c/div>\u003c/div>\n        \u003cdiv class=\"\" data-step=\"2\">\u003cdiv class=\"pj-st\">\u003cdiv class=\"l\">La droite de demande globale\u003c/div>\u003cdiv class=\"v\">\u003cspan class=\"k-dep\">DG\u003c/span> = \u003cspan class=\"k-dep\">400\u003c/span> + \u003cspan class=\"k-conso\">0,6\u003c/span> \u003cspan class=\"k-vol\">\u003cvar>Y\u003c/var>\u003c/span>\u003c/div>\u003c/div>\u003c/div>\n      \u003c/div>\u003c/div>\u003c/div>","source":"Exemple fictif : économie fermée, sans impôts ni importations, prix fixes ; consommation autonome 100, investissement 150, dépenses publiques 150 (milliards).","prov":"fictif"},{"id":"dg-q","title":"Que devient la droite si l'investissement baisse&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:24px\">\u003cdiv style=\"max-width:1200px\">\n      \u003cdiv>\u003cdiv class=\"ask\">Les entreprises investissent 50 de moins. La droite DG…\u003c/div>\u003cdiv class=\"choices inline\" id=\"pj-dg\">\u003cbutton class=\"choice\" data-choice=\"A\">\u003cspan class=\"letter\">A\u003c/span>\u003cspan>elle descend de 50\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"B\">\u003cspan class=\"letter\">B\u003c/span>\u003cspan>elle pivote\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"C\">\u003cspan class=\"letter\">C\u003c/span>\u003cspan>elle ne bouge pas\u003c/span>\u003c/button>\u003c/div>\u003c/div>\n      \u003c/div>\n    \u003c/div>","source":"Question de prédiction ; même économie, DG = 400 + 0,6 Y.","prov":null},{"id":"dg-scen","title":"Déplacer ou faire pivoter la droite","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-row\" style=\"gap:40px\">\n      \u003cdiv style=\"flex:0 0 720px\">\u003cdiv id=\"pj-dgs\" style=\"width:720px;height:620px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow\">\u003cdiv id=\"pj-dgs-card\">\u003c/div>\u003c/div>\u003c/div>\u003cspan class=\"p-mark\" data-step=\"1\">\u003c/span>\u003cspan class=\"p-mark\" data-step=\"2\">\u003c/span>","source":"Exemple fictif (DG = 400 + 0,6 Y au départ, en gris).","prov":"fictif"},{"id":"eq-q","title":"Et si les entreprises produisent 800&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:24px\">\u003cdiv style=\"max-width:1240px\">\n      \u003cdiv>\u003cdiv class=\"ask\">Elles produisent 800. La demande vaut 400 + 0,6 × 800 = 880. Que se passe-t-il ?\u003c/div>\u003cdiv class=\"choices \" id=\"pj-eq\">\u003cbutton class=\"choice\" data-choice=\"A\">\u003cspan class=\"letter\">A\u003c/span>\u003cspan>les stocks baissent : elles produisent davantage\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"B\">\u003cspan class=\"letter\">B\u003c/span>\u003cspan>les stocks montent : elles produisent moins\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"C\">\u003cspan class=\"letter\">C\u003c/span>\u003cspan>rien ne change\u003c/span>\u003c/button>\u003c/div>\u003c/div>\n      \u003c/div>\n    \u003c/div>","source":"Question de prédiction ; même économie, DG = 400 + 0,6 Y.","prov":null},{"id":"equilibre","title":"Pourquoi la production s'arrête-t-elle à l'intersection&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-row\" style=\"gap:40px\">\n      \u003cdiv style=\"flex:0 0 720px\">\u003cdiv id=\"pj-eq-chart\" style=\"width:720px;height:620px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow\">\u003cdiv id=\"pj-eq-card\">\u003c/div>\u003c/div>\u003c/div>\u003cspan class=\"p-mark\" data-step=\"1\">\u003c/span>\u003cspan class=\"p-mark\" data-step=\"2\">\u003c/span>\u003cspan class=\"p-mark\" data-step=\"3\">\u003c/span>","source":"Exemple fictif : DG = 400 + 0,6 Y ; axes tronqués (600 à 1 200).","prov":"fictif"},{"id":"eq-fiche","title":"L'équilibre de la croix keynésienne","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\">\u003cdiv style=\"max-width:1300px;margin:0 auto;width:100%\">\u003cdiv class=\"fiche \">\u003cdiv class=\"fiche-head\">\u003cspan class=\"fiche-lbl\">À savoir utiliser\u003c/span>\u003cspan class=\"fiche-name\">Équilibre de la croix keynésienne\u003c/span>\u003c/div>\u003cdiv class=\"fiche-f\">\u003cspan class=\"k-vol\">\u003cvar>Y\u003c/var>\u003c/span> = \u003cspan class=\"k-dep\">DG\u003c/span> ⟺ \u003cspan class=\"k-vol\">\u003cvar>Y\u003c/var>\u003c/span> = \u003cspan class=\"k-dep\">\u003cvar>A\u003c/var>\u003c/span> + \u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span> \u003cspan class=\"k-vol\">\u003cvar>Y\u003c/var>\u003c/span> ⟺ \u003cspan class=\"k-vol\">\u003cvar>Y\u003c/var>\u003c/span> = \u003cspan class=\"k-dep\">\u003cvar>A\u003c/var>\u003c/span> / (1 − \u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span>)\u003c/div>\u003cdiv class=\"fiche-ex\" data-step=\"1\">\u003cspan class=\"lbl\">Exemple\u003c/span>\u003cspan class=\"k-dep\">400\u003c/span> / (1 − \u003cspan class=\"k-conso\">0,6\u003c/span>) = \u003cspan class=\"k-vol\">1 000\u003c/span> : les stocks ne varient plus.\u003c/div>\u003cdiv class=\"fiche-trap\" data-step=\"2\">\u003cspan class=\"lbl\">Piège\u003c/span>croire que cet équilibre est la production potentielle : l'économie peut s'y installer avec du chômage (partie 3).\u003c/div>\u003c/div>\u003c/div>\u003c/div>","prov":"fictif"},{"id":"mu-q","title":"De combien la production baisse-t-elle&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:24px\">\u003cdiv style=\"max-width:1200px\">\n      \u003cdiv>\u003cdiv class=\"ask\">L'État dépense 40 de moins (de 150 à 110), avec c = 0,6. La production baisse de…\u003c/div>\u003cdiv class=\"choices inline\" id=\"pj-mu\">\u003cbutton class=\"choice\" data-choice=\"A\">\u003cspan class=\"letter\">A\u003c/span>\u003cspan>− 24\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"B\">\u003cspan class=\"letter\">B\u003c/span>\u003cspan>− 40\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"C\">\u003cspan class=\"letter\">C\u003c/span>\u003cspan>− 100\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"D\">\u003cspan class=\"letter\">D\u003c/span>\u003cspan>− 400\u003c/span>\u003c/button>\u003c/div>\u003c/div>\n      \u003c/div>\n    \u003c/div>","source":"Question de prédiction ; même économie, DG = 400 + 0,6 Y, équilibre à 1 000.","prov":null},{"id":"mu-tours","title":"Mes dépenses sont vos revenus","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-row\" style=\"gap:40px\">\n      \u003cdiv style=\"flex:0 0 720px\">\u003cdiv id=\"pj-mu-chart\" style=\"width:720px;height:620px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow\">\u003cdiv class=\"pj-steps\">\n        \u003cdiv>\u003cdiv class=\"pj-st\">\u003cdiv class=\"l\">Tour 1 · l'État commande moins : la droite descend de\u003c/div>\u003cdiv class=\"v\">\u003cspan class=\"k-dep\">− 40\u003c/span>\u003c/div>\u003c/div>\u003c/div>\n        \u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"pj-st\">\u003cdiv class=\"l\">Tour 2 · les revenus perdus réduisent la consommation\u003c/div>\u003cdiv class=\"v\">0,6 × 40 = \u003cspan class=\"k-conso\">− 24\u003c/span>, puis 14,4, puis 8,6…\u003c/div>\u003c/div>\u003c/div>\n        \u003cdiv class=\"\" data-step=\"2\">\u003cdiv class=\"pj-st\">\u003cdiv class=\"l\">Tous les tours\u003c/div>\u003cdiv class=\"v\">40 / (1 − 0,6) = \u003cspan class=\"k-vol\">− 100\u003c/span>\u003c/div>\u003c/div>\u003c/div>\n      \u003c/div>\u003c/div>\u003c/div>","source":"Exemple fictif : DG = 400 + 0,6 Y, équilibre de départ à 1 000 ; prix fixes. Somme des tours : 40 × (1 + \u003cvar>c\u003c/var> + \u003cvar>c\u003c/var>\u003csup>2\u003c/sup> + …) = 40 / (1 − \u003cvar>c\u003c/var>).","prov":"fictif"},{"id":"mu-c","title":"Plus la droite est pentue, plus l'équilibre recule","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-row\" style=\"gap:40px\">\n      \u003cdiv style=\"flex:0 0 720px\">\u003cdiv id=\"pj-muc-chart\" style=\"width:720px;height:620px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow\">\u003cdiv id=\"pj-muc-card\">\u003c/div>\u003c/div>\u003c/div>\u003cspan class=\"p-mark\" data-step=\"1\">\u003c/span>\u003cspan class=\"p-mark\" data-step=\"2\">\u003c/span>","source":"Simulation : même baisse de 40 ; la dépense autonome de départ est ajustée pour garder l'équilibre à 1 000.","prov":"sim"},{"id":"mu-fiche","title":"Le multiplicateur joue dans les deux sens","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\">\u003cdiv style=\"max-width:1240px;margin:0 auto;width:100%\">\u003cdiv class=\"fiche \">\u003cdiv class=\"fiche-head\">\u003cspan class=\"fiche-lbl\">À savoir utiliser\u003c/span>\u003cspan class=\"fiche-name\">Multiplicateur\u003c/span>\u003c/div>\u003cdiv class=\"fiche-f\">\u003cspan class=\"k-res\">\u003cvar>k\u003c/var>\u003c/span> = Δ\u003cspan class=\"k-vol\">\u003cvar>Y\u003c/var>\u003c/span> / Δ\u003cspan class=\"k-dep\">\u003cvar>A\u003c/var>\u003c/span> = 1 / (1 − \u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span>)\u003c/div>\u003cdiv class=\"fiche-ex\" data-step=\"1\">\u003cspan class=\"lbl\">Exemple\u003c/span>\u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span> = 0,6 : \u003cspan class=\"k-res\">\u003cvar>k\u003c/var>\u003c/span> = 2,5 ; Δ\u003cspan class=\"k-dep\">\u003cvar>G\u003c/var>\u003c/span> = − 40 donne Δ\u003cspan class=\"k-vol\">\u003cvar>Y\u003c/var>\u003c/span> = \u003cspan class=\"k-vol\">− 100\u003c/span>.\u003c/div>\u003cdiv class=\"fiche-trap\" data-step=\"2\">\u003cspan class=\"lbl\">Piège\u003c/span>oublier que le multiplicateur joue aussi à la baisse : une économie de dépenses réduit la production de plus que son montant.\u003c/div>\u003c/div>\u003c/div>\u003c/div>","prov":"fictif"},{"id":"fu-q","title":"Et avec des impôts&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:24px\">\u003cdiv style=\"max-width:1240px\">\n      \u003cdiv>\u003cdiv class=\"ask\">L'État prélève 0,5 euro d'impôts sur chaque euro de production. La même baisse de 40 des dépenses publiques fait baisser la production de…\u003c/div>\u003cdiv class=\"choices inline\" id=\"pj-fu\">\u003cbutton class=\"choice\" data-choice=\"A\">\u003cspan class=\"letter\">A\u003c/span>\u003cspan>plus de 100\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"B\">\u003cspan class=\"letter\">B\u003c/span>\u003cspan>100\u003c/span>\u003c/button>\u003cbutton class=\"choice\" data-choice=\"C\">\u003cspan class=\"letter\">C\u003c/span>\u003cspan>moins de 100\u003c/span>\u003c/button>\u003c/div>\u003c/div>\n      \u003c/div>\n    \u003c/div>","source":"Question de prédiction ; c = 0,6.","prov":null},{"id":"fuites","title":"Les impôts et les importations aplatissent la droite","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-row\" style=\"gap:40px\">\n      \u003cdiv style=\"flex:0 0 720px\">\u003cdiv id=\"pj-fu-chart\" style=\"width:720px;height:620px\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"p-grow\">\u003cdiv id=\"pj-fu-card\">\u003c/div>\u003c/div>\u003c/div>\u003cspan class=\"p-mark\" data-step=\"1\">\u003c/span>\u003cspan class=\"p-mark\" data-step=\"2\">\u003c/span>\u003cspan class=\"p-mark\" data-step=\"3\">\u003c/span>","source":"Simulation, c = 0,6 ; en gris, l'économie sans fuites. France, 2025 : prélèvements obligatoires 43,6 % du PIB, importations 34,2 % du PIB (\u003ca href=\"https://www.insee.fr/fr/statistiques/8997691\" target=\"_blank\" rel=\"noopener noreferrer\">Insee (mai 2026)\u003c/a> ; \u003ca href=\"https://www.insee.fr/fr/statistiques/8988823?sommaire=8988934\" target=\"_blank\" rel=\"noopener noreferrer\">Insee, comptes nationaux annuels base 2020 (tableaux 1.101 et 1.102, mai 2026)\u003c/a>), des moyennes et non des propensions marginales.","prov":"sim"},{"id":"fu-fiche","title":"Un multiplicateur plus faible, des chocs amortis","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\">\u003cdiv style=\"max-width:1300px;margin:0 auto;width:100%\">\u003cdiv class=\"fiche \">\u003cdiv class=\"fiche-head\">\u003cspan class=\"fiche-lbl\">À savoir utiliser\u003c/span>\u003cspan class=\"fiche-name\">Multiplicateur avec fuites\u003c/span>\u003c/div>\u003cdiv class=\"fiche-f\">\u003cspan class=\"k-res\">\u003cvar>k\u003c/var>\u003c/span> = 1 / (1 − \u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span> (1 − \u003cspan class=\"k-moins\">\u003cvar>t\u003c/var>\u003c/span>) + \u003cspan class=\"k-moins\">\u003cvar>m\u003c/var>\u003c/span>)\u003c/div>\u003cdiv class=\"fiche-vars inline\">\u003cspan class=\"vp\">\u003cspan class=\"sym\">\u003cspan class=\"k-moins\">\u003cvar>t\u003c/var>\u003c/span>\u003c/span>\u003cspan class=\"mean\">part d'un euro de production prélevée en impôts\u003c/span>\u003c/span>\u003cspan class=\"vp\">\u003cspan class=\"sym\">\u003cspan class=\"k-moins\">\u003cvar>m\u003c/var>\u003c/span>\u003c/span>\u003cspan class=\"mean\">part dépensée en importations\u003c/span>\u003c/span>\u003c/div>\u003cdiv class=\"fiche-ex\" data-step=\"1\">\u003cspan class=\"lbl\">Exemple\u003c/span>\u003cspan class=\"k-conso\">\u003cvar>c\u003c/var>\u003c/span> = 0,6, \u003cspan class=\"k-moins\">\u003cvar>t\u003c/var>\u003c/span> = 0,5, \u003cspan class=\"k-moins\">\u003cvar>m\u003c/var>\u003c/span> = 0,3 : pente 0,3 − 0,3 = 0, donc \u003cspan class=\"k-res\">\u003cvar>k\u003c/var>\u003c/span> = \u003cspan class=\"k-res\">1\u003c/span>, contre 2,5 sans fuites.\u003c/div>\u003cdiv class=\"fiche-trap\" data-step=\"2\">\u003cspan class=\"lbl\">Piège\u003c/span>écrire \u003cvar>c\u003c/var> − \u003cvar>t\u003c/var> au lieu de \u003cvar>c\u003c/var> (1 − \u003cvar>t\u003c/var>) : les impôts réduisent le revenu disponible.\u003c/div>\u003c/div>\u003c/div>\u003c/div>","prov":"fictif"},{"id":"hypotheses","title":"Que suppose la croix keynésienne&#8239;?","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\">\u003cdiv class=\"p-grid2\" style=\"gap:24px 32px\">\u003cdiv>\u003cdiv class=\"pj-card\" style=\"height:100%\">\u003cdiv class=\"h big\">Les prix sont fixes\u003c/div>\u003cp>Les entreprises servent la demande au prix affiché.\u003c/p>\u003cp class=\"pj-where\">Prix et chocs d'offre : chapitre 5\u003c/p>\u003c/div>\u003c/div>\u003cdiv class=\"\" data-step=\"1\">\u003cdiv class=\"pj-card\" style=\"height:100%\">\u003cdiv class=\"h big\">Des capacités sont disponibles\u003c/div>\u003cp>Près de la production potentielle, une demande plus forte fait surtout monter les prix.\u003c/p>\u003cp class=\"pj-where\">Potentiel : partie 3\u003c/p>\u003c/div>\u003c/div>\u003cdiv class=\"\" data-step=\"2\">\u003cdiv class=\"pj-card\" style=\"height:100%\">\u003cdiv class=\"h big\">Le taux d'intérêt ne bouge pas\u003c/div>\u003cp>Si la banque centrale baisse ses taux quand l'État coupe ses dépenses, la production baisse moins.\u003c/p>\u003cp class=\"pj-where\">Politique monétaire : partie 4\u003c/p>\u003c/div>\u003c/div>\u003cdiv class=\"\" data-step=\"3\">\u003cdiv class=\"pj-card\" style=\"height:100%\">\u003cdiv class=\"h big\">La consommation suit le revenu du moment\u003c/div>\u003cp>Des ménages qui craignent le chômage ou des impôts futurs dépensent moins.\u003c/p>\u003cp class=\"pj-where\">Épargne de précaution : partie 3\u003c/p>\u003c/div>\u003c/div>\u003c/div>\u003c/div>","prov":null},{"id":"p2-verif1","title":"Trouver l'équilibre et l'effet d'un choc","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:36px\">\n      \u003cp class=\"p-txt\">\u003cspan class=\"pj-tag\">Vérifiez · 1 minute\u003c/span> \u003cspan class=\"k-dep\">DG\u003c/span> = \u003cspan class=\"k-dep\">300\u003c/span> + \u003cspan class=\"k-conso\">0,5\u003c/span> \u003cvar>Y\u003c/var>. Quelle est la production d'équilibre ? Que devient-elle si l'investissement baisse de \u003cspan class=\"k-dep\">20\u003c/span> ?\u003c/p>\n      \u003c/div>","source":"Exemple fictif.","prov":"fictif"},{"id":"p2-verif2","title":"Calculer un multiplicateur avec fuites","part":"Partie 2 · Dépenser moins, produire moins ?","html":"\u003cdiv class=\"p-center\" style=\"gap:36px\">\n      \u003cp class=\"p-txt\">\u003cspan class=\"pj-tag\">Vérifiez · 1 minute\u003c/span> Avec \u003cspan class=\"k-conso\">c = 0,5\u003c/span>, \u003cspan class=\"k-moins\">t = 0,2\u003c/span> et \u003cspan class=\"k-moins\">m = 0,2\u003c/span>, quelle est la pente de la droite DG, et le multiplicateur ?\u003c/p>\n      \u003c/div>","source":"Exemple fictif.","prov":"fictif"}];
